mapper.select:
SELECT COUNT(*) > 0
FROM interested_legal_district
WHERE legal_district_code = #{code} AND member_uuid = #{memberUuid};


SELECT id, code AS region_code, sido_name, gugun_name, dong_name
FROM interested_legal_district i
JOIN legal_district l ON i.legal_district_code = l.code
WHERE member_uuid = #{memberUuid}
ORDER BY id DESC
LIMIT #{requestDto.limitPlusOne} 
OFFSET #{requestDto.offset};
